def parse_csv(text):
    rows = []
    current_row = []
    current_field = []
    in_quotes = False
    i = 0
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    if text.endswith('\n'):
        text = text[:-1]
    while i < len(text):
        char = text[i]
        if in_quotes:
            if char == '"':
                if i + 1 < len(text) and text[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                    continue
                else:
                    in_quotes = False
                    i += 1
                    continue
            else:
                current_field.append(char)
                i += 1
                continue
        else:
            if char == '"':
                in_quotes = True
                i += 1
                continue
            elif char == ',':
                current_row.append(''.join(current_field))
                current_field = []
                i += 1
                continue
            elif char == '\n':
                current_row.append(''.join(current_field))
                current_field = []
                rows.append(current_row)
                current_row = []
                i += 1
                continue
            else:
                current_field.append(char)
                i += 1
                continue
    if current_field or current_row:
        current_row.append(''.join(current_field))
        rows.append(current_row)
    if not rows:
        return []
    headers = rows[0]
    result = []
    for row in rows[1:]:
        d = {}
        for j, header in enumerate(headers):
            if j < len(row):
                d[header] = row[j]
            else:
                d[header] = ''
        result.append(d)
    return result

