def normalize(path):
    if not path:
        return '.'

    is_absolute = path.startswith('/')
    parts = path.split('/')

    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if is_absolute:
        return '/' + '/'.join(stack) if stack else '/'
    else:
        return '/'.join(stack) if stack else '.'
```

