def parse_query(qs):
    if not qs:
        return {}

    result = {}
    pairs = qs.split('&')

    for pair in pairs:
        if not pair:
            continue
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''

        # Decode percent-encoding and '+' as space
        def decode(s):
            s = s.replace('+', ' ')
            parts = []
            i = 0
            while i < len(s):
                if s[i] == '%' and i + 2 < len(s):
                    try:
                        hex_val = s[i+1:i+3]
                        parts.append(chr(int(hex_val, 16)))
                        i += 3
                    except ValueError:
                        parts.append(s[i])
                        i += 1
                else:
                    parts.append(s[i])
                    i += 1
            return ''.join(parts)

        key = decode(key)
        value = decode(value)

        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    return result
```

