module.exports = function debounceCount(fn, ms) {
  let timer = null;

  function invoke() {
    fn();
    timer = null;
  }

  function call() {
    if (timer) {
      clearTimeout(timer);
    }
    timer = setTimeout(invoke, ms);
  }

  function flush() {
    if (timer) {
      clearTimeout(timer);
      invoke();
    }
  }

  return { call, flush };
};

