```typescript
export function debounceState(): { pending: boolean; mark(): void; clear(): void } {
  let pending = false;
  let timer: ReturnType<typeof setTimeout> | null = null;

  function mark(): void {
    if (timer !== null) {
      clearTimeout(timer);
    }
    pending = true;
    timer = setTimeout(() => {
      pending = false;
      timer = null;
    }, 0);
  }

  function clear(): void {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    pending = false;
  }

  return { pending, mark, clear };
}
```

